    /**
     * Turns a synthesized calendar class into a stored row the owner owns (story 323).
     *
     * Everything is copied from the event — including `metadata`, which carries the start instant
     * plus the location and `htmlLink`, so the row keeps a way back to what it came from. The
     * `external_id` is the event's, which is what makes this idempotent: `idx_activities_external_id`
     * is unique, so a duplicate POST is a `ConflictError` rather than a second row, and the merge
     * recognises the class as adopted by exact id from then on.
     *
     * `id` is deliberately *not* sent: the projection's `cal_<eventId>` is not a row id, and the
     * server mints a uuidv7 like it does for any other activity.
     */
    static adoptCalendarActivity(event: Activity): Promise<Activity> {
        return HealthService.createActivity({
            type: event.type,
            source: 'calendar',
            title: event.title,
            date: event.date,
            description: event.description,
            duration_minutes: event.duration_minutes,
            calories_burned: event.calories_burned,
            external_id: event.external_id,
            metadata: event.metadata,
        });
    }

