    /**
     * Bypasses the JSON client: story 310's duplicate-meal choice is driven by
     * the server's own `{ error }` text, shown to the user as-is.
     */
    static async acceptEstimateJob(
        id: string,
        // Story 310: `on_duplicate` says what to do when the estimate lands on an
        // existing meal's exact ingredient set. Omitted means create a new meal —
        // the server's default too, so the choice is opt-in on both sides.
        opts: { log?: boolean; consumed_at?: string; on_duplicate?: OnDuplicateAction } = {},
    ): Promise<{ kind: 'meal' | 'food_item'; meal_id?: string; food_item_id?: string; logged: boolean; reused?: boolean }> {
        const response = await fetch(`${HEALTH_ROOT}/food-items/estimate-jobs/${encodeURIComponent(id)}/accept`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ log: opts.log ?? true, consumed_at: opts.consumed_at, on_duplicate: opts.on_duplicate }),
        });
        if (!response.ok) {
            const data = await response.json().catch(() => ({}));
            throw new Error(data.error ?? `Failed to accept estimate: ${response.status}`);
        }
        return response.json();
    }

