    /**
     * Create-or-update the cardio_details for an activity. The server upserts and
     * overwrites every column, so callers must send the full desired state (an
     * all-empty payload deletes the row → 204). Returns the row, or null when deleted.
     *
     * Bypasses the JSON client: the null here is a 204 on a write, not an absent
     * read, so neither `patch` nor `find` describes it.
     */
    static async upsertCardioDetails(activityId: string, payload: Partial<NewCardioDetails>): Promise<CardioDetails | null> {
        const response = await fetch(`${HEALTH_ROOT}/cardio-details/${encodeURIComponent(activityId)}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
        });
        if (response.status === 204) return null;
        if (!response.ok) throw await apiError(response, `PATCH /cardio-details/${activityId}`);
        return response.json();
    }

